        "뚜레 2026-05-14 · 민트 초기 성능 평가·정성적 투자 기준(evaluation only): 스킬 고정 레벨 숫자열 미제시. 1스킬·버스트는 직접 딜 투자 정도에 따라, 2스킬은 오버로드 크리티컬 확률을 보고 계산. 오버로드 오버로드 기본 적용+소장품 중심. 장탄·차지 속도는 불필요로 기재. 츠바이 조합을 목적으로 키웠다면 다른 곳에도 활용할 수 있으나 범용 육성 대상으로 먼저 키우는 것은 권하지 않는다는 초기 평가. 프리카 스킬 공개 전 리뷰이며 파트너 공개까지 판단을 유보한다. PvP는 버스트 수급과 시작 효과가 부족해 부정적이다.",
        "Prydwen (2026.10.28 확인): PvE 스킬 4/4/4 → 7/4/7 → 10/7/10 (→ 10/10/10) / PvP 스킬 4/4/4 → 4/1/4 → 7/1/7 (→ 10/4/10) / 오버로드 장탄 1~2줄 / 역할: 버퍼·힐러 / 현재 평가: 스토리S·보스SS·PvPB"
